"""Team Alpha. Write use cases for placements. Each one is atomic and emits a domain event."""

from decimal import Decimal, InvalidOperation

from django.db import transaction
from django.utils import timezone

from apps.accounts import selectors as accounts_selectors
from apps.accounts.services import UserService
from apps.core import events
from apps.core.enums import Role
from apps.core.exceptions import InvalidTransition, NotAllowed, RuleViolation

from .models import GradeBand, Organization, Placement

Status = Placement.Status

EDITABLE_FIELDS = {
    "role_title",
    "department",
    "task_description",
    "start_date",
    "end_date",
    "proposed_supervisor_name",
    "proposed_supervisor_email",
    "proposed_supervisor_phone",
}
REQUIRED_TO_SUBMIT = (
    "role_title",
    "task_description",
    "proposed_supervisor_name",
    "proposed_supervisor_email",
)
BLOCKING_STATUSES = (Status.REJECTED, Status.TERMINATED)
ORGANIZATION_FIELDS = {"name", "address", "county", "contact_email", "contact_phone"}


def _require_role(actor, *roles) -> None:
    if getattr(actor, "role", None) not in roles:
        raise NotAllowed()


def _check_fields(fields: dict) -> None:
    unknown = set(fields) - EDITABLE_FIELDS
    if unknown:
        raise RuleViolation(f"Unknown field(s): {', '.join(sorted(unknown))}.", code="bad_field")


def _validate_dates(period, start, end) -> None:
    if start is None or end is None:
        raise RuleViolation("Start and end dates are required.", code="dates_required")
    if end < start:
        raise RuleViolation("The end date is before the start date.", code="dates_ordered")
    if start < period.start_date or end > period.end_date:
        raise RuleViolation(
            "Placement dates must lie inside the internship period.", code="dates_outside_period"
        )


def _check_organization_usable(actor, organization) -> None:
    if actor.role == Role.STUDENT and not (
        organization.is_verified or organization.created_by_id == actor.id
    ):
        raise RuleViolation("This organisation is not available.", code="organization_unavailable")


def _save(placement, actor, **fields) -> Placement:
    for name, value in fields.items():
        setattr(placement, name, value)
    placement._history_user = actor
    placement.save()
    return placement


def _supervisor(user_id, role):
    user = accounts_selectors.get_active_user_with_role(user_id, role)
    if user is None:
        raise RuleViolation(
            "Supervisor not found, inactive, or has the wrong role.", code="invalid_supervisor"
        )
    return user


def _remarks_required(remarks: str) -> str:
    remarks = (remarks or "").strip()
    if not remarks:
        raise RuleViolation("Remarks are required.", code="remarks_required")
    return remarks


class OrganizationService:
    @staticmethod
    def create(*, actor, **fields) -> Organization:
        _require_role(actor, Role.STUDENT, Role.COORDINATOR)
        return Organization.objects.create(
            created_by=actor, is_verified=actor.role == Role.COORDINATOR, **fields
        )

    @staticmethod
    def update(*, actor, organization, **fields) -> Organization:
        _require_role(actor, Role.STUDENT, Role.COORDINATOR)
        if actor.role == Role.STUDENT and (
            organization.created_by_id != actor.id or organization.is_verified
        ):
            raise NotAllowed("Only your own unverified organisations can be edited.")
        for name, value in fields.items():
            if name in ORGANIZATION_FIELDS:
                setattr(organization, name, value)
        organization.save()
        return organization

    @staticmethod
    def verify(*, actor, organization) -> Organization:
        _require_role(actor, Role.COORDINATOR)
        organization.is_verified = True
        organization.save(update_fields=["is_verified", "updated_at"])
        return organization


class PeriodService:
    @staticmethod
    @transaction.atomic
    def set_grade_bands(period, bands) -> list:
        """Replace the period's grade bands. Needs a band starting at 0 so everyone gets a grade."""
        cleaned, percents, labels = [], set(), set()
        for band in bands:
            try:
                percent = Decimal(str(band["min_percent"]))
            except (InvalidOperation, KeyError):
                raise RuleViolation(
                    "Each band needs a numeric min_percent.", code="bad_band"
                ) from None
            label = str(band.get("label", "")).strip()
            if not label or not Decimal(0) <= percent <= Decimal(100):
                raise RuleViolation(
                    "Bands need a label and a percent from 0 to 100.", code="bad_band"
                )
            if percent in percents or label in labels:
                raise RuleViolation("Band percents and labels must be unique.", code="bad_band")
            percents.add(percent)
            labels.add(label)
            cleaned.append((percent, label))
        if Decimal(0) not in percents:
            raise RuleViolation("Include a band that starts at 0.", code="band_zero_missing")
        period.grade_bands.all().delete()
        GradeBand.objects.bulk_create(
            [GradeBand(period=period, min_percent=p, label=label) for p, label in cleaned]
        )
        return list(period.grade_bands.order_by("-min_percent"))


class PlacementService:
    @staticmethod
    @transaction.atomic
    def create_draft(*, actor, period, organization, student=None, **fields) -> Placement:
        if actor.role == Role.STUDENT:
            student = actor
        elif actor.role == Role.COORDINATOR:
            if student is None:
                raise RuleViolation("A student is required.", code="student_required")
        else:
            raise NotAllowed()
        if student.role != Role.STUDENT:
            raise RuleViolation("The selected user is not a student.", code="not_a_student")
        _check_fields(fields)
        _check_organization_usable(actor, organization)
        _validate_dates(period, fields.get("start_date"), fields.get("end_date"))
        existing = Placement.objects.filter(student=student, period=period)
        if existing.exclude(status__in=BLOCKING_STATUSES).exists():
            raise RuleViolation(
                "This student already has a placement in this period.", code="placement_exists"
            )
        placement = Placement(
            student=student, period=period, organization=organization, status=Status.DRAFT, **fields
        )
        placement._history_user = actor
        placement.save()
        return placement

    @staticmethod
    @transaction.atomic
    def update(*, actor, placement, organization=None, **fields) -> Placement:
        if actor.role == Role.STUDENT:
            if placement.student_id != actor.id:
                raise NotAllowed()
            if placement.status not in (Status.DRAFT, Status.RETURNED):
                raise InvalidTransition("Only draft or returned placements can be edited.")
        elif actor.role == Role.COORDINATOR:
            if placement.status in (Status.REJECTED, Status.COMPLETED, Status.TERMINATED):
                raise InvalidTransition("This placement can no longer be edited.")
        else:
            raise NotAllowed()
        _check_fields(fields)
        if organization is not None:
            _check_organization_usable(actor, organization)
            placement.organization = organization
        for name, value in fields.items():
            setattr(placement, name, value)
        _validate_dates(placement.period, placement.start_date, placement.end_date)
        return _save(placement, actor)

    @staticmethod
    @transaction.atomic
    def submit(*, actor, placement) -> Placement:
        _require_role(actor, Role.STUDENT)
        if placement.student_id != actor.id:
            raise NotAllowed()
        placement.ensure_transition(Status.SUBMITTED)
        missing = [name for name in REQUIRED_TO_SUBMIT if not str(getattr(placement, name)).strip()]
        if missing:
            raise RuleViolation(
                "Complete the placement details before submitting.",
                code="incomplete_placement",
                details={"missing": missing},
            )
        _validate_dates(placement.period, placement.start_date, placement.end_date)
        _save(placement, actor, status=Status.SUBMITTED, submitted_at=timezone.now())
        events.emit(
            events.placement_submitted,
            sender=PlacementService,
            placement_id=placement.id,
            actor_id=actor.id,
        )
        return placement

    @staticmethod
    @transaction.atomic
    def approve(
        *,
        actor,
        placement,
        academic_supervisor_id,
        workplace_supervisor_id=None,
        invite_workplace_supervisor=False,
        remarks="",
    ) -> Placement:
        _require_role(actor, Role.COORDINATOR)
        placement.ensure_transition(Status.APPROVED)
        academic = _supervisor(academic_supervisor_id, Role.ACADEMIC_SUPERVISOR)
        if workplace_supervisor_id:
            workplace = _supervisor(workplace_supervisor_id, Role.WORKPLACE_SUPERVISOR)
        elif invite_workplace_supervisor:
            if not (placement.proposed_supervisor_name and placement.proposed_supervisor_email):
                raise RuleViolation(
                    "The student did not propose a supervisor to invite.",
                    code="no_proposed_supervisor",
                )
            workplace = UserService.invite_workplace_supervisor(
                name=placement.proposed_supervisor_name,
                email=placement.proposed_supervisor_email,
                phone=placement.proposed_supervisor_phone,
                organization=placement.organization,
                placement_id=placement.id,
            )
        else:
            raise RuleViolation(
                "Choose a workplace supervisor or invite the proposed one.",
                code="workplace_supervisor_required",
            )
        Organization.objects.filter(pk=placement.organization_id).update(is_verified=True)
        _save(
            placement,
            actor,
            status=Status.APPROVED,
            academic_supervisor=academic,
            workplace_supervisor=workplace,
            coordinator_remarks=(remarks or "").strip(),
            decided_by=actor,
            decided_at=timezone.now(),
        )
        events.emit(
            events.placement_approved,
            sender=PlacementService,
            placement_id=placement.id,
            actor_id=actor.id,
        )
        return placement

    @staticmethod
    @transaction.atomic
    def return_for_changes(*, actor, placement, remarks) -> Placement:
        _require_role(actor, Role.COORDINATOR)
        placement.ensure_transition(Status.RETURNED)
        remarks = _remarks_required(remarks)
        _save(
            placement,
            actor,
            status=Status.RETURNED,
            coordinator_remarks=remarks,
            decided_by=actor,
            decided_at=timezone.now(),
        )
        events.emit(
            events.placement_returned,
            sender=PlacementService,
            placement_id=placement.id,
            actor_id=actor.id,
            remarks=remarks,
        )
        return placement

    @staticmethod
    @transaction.atomic
    def reject(*, actor, placement, remarks) -> Placement:
        _require_role(actor, Role.COORDINATOR)
        placement.ensure_transition(Status.REJECTED)
        remarks = _remarks_required(remarks)
        _save(
            placement,
            actor,
            status=Status.REJECTED,
            coordinator_remarks=remarks,
            decided_by=actor,
            decided_at=timezone.now(),
        )
        events.emit(
            events.placement_rejected,
            sender=PlacementService,
            placement_id=placement.id,
            actor_id=actor.id,
            remarks=remarks,
        )
        return placement

    @staticmethod
    @transaction.atomic
    def assign_supervisors(
        *, actor, placement, academic_supervisor_id=None, workplace_supervisor_id=None
    ) -> Placement:
        _require_role(actor, Role.COORDINATOR)
        if placement.status != Status.APPROVED:
            raise InvalidTransition("Supervisors can only be changed on approved placements.")
        changes = {}
        if academic_supervisor_id:
            changes["academic_supervisor"] = _supervisor(
                academic_supervisor_id, Role.ACADEMIC_SUPERVISOR
            )
        if workplace_supervisor_id:
            changes["workplace_supervisor"] = _supervisor(
                workplace_supervisor_id, Role.WORKPLACE_SUPERVISOR
            )
        if not changes:
            raise RuleViolation("Nothing to change.", code="nothing_to_change")
        return _save(placement, actor, **changes)

    @staticmethod
    @transaction.atomic
    def complete(*, actor, placement) -> Placement:
        _require_role(actor, Role.COORDINATOR)
        placement.ensure_transition(Status.COMPLETED)
        return _save(placement, actor, status=Status.COMPLETED)

    @staticmethod
    @transaction.atomic
    def terminate(*, actor, placement, reason) -> Placement:
        _require_role(actor, Role.COORDINATOR)
        placement.ensure_transition(Status.TERMINATED)
        reason = _remarks_required(reason)
        return _save(placement, actor, status=Status.TERMINATED, coordinator_remarks=reason)
